#!/usr/bin/env python3
# -*- coding: utf-8 -*-

# Author: Rensc
# Date: 2026-08-09
# Version: dev001
# Function: Summarize shared, specific, and statistically testable SeRP overlap peaks.
# Input: Output prefix generated by serp_overlap.
# Output: Peak classification, category, transcript, gene, cluster, and significance summary tables.

"""Summary workflow for pairwise SeRP overlap-analysis results."""

from __future__ import annotations

from pathlib import Path
import re

import numpy as np
import pandas as pd


class SeRPOverlapSummary:
    """Summarize shared and condition-specific SeRP overlap results.

    Parameters
    ----------
    args : argparse.Namespace
        Parsed command-line arguments from ``serp_summary``.

    Notes
    -----
    ``specific`` describes condition specificity according to the interval-overlap
    criteria used by ``serp_overlap``. Statistical significance is annotated
    separately from ``BHFDR`` or ``P_Value`` and never changes the shared/specific
    classification.
    """

    REQUIRED_SHARED_COLUMNS = {
        "transcripts",
        "peak_start",
        "peak_end",
        "comparison_sample",
        "overlap_status",
    }
    REQUIRED_CLUSTER_COLUMNS = {
        "cluster_id",
        "transcripts",
        "relationship_type",
        "peak_count_a",
        "peak_count_b",
    }
    REQUIRED_RELATIONSHIP_COLUMNS = {
        "transcripts",
        "peak_uid_a",
        "peak_uid_b",
        "overlap_length",
        "reciprocal_overlap",
        "jaccard",
        "qualifying_overlap",
    }

    def __init__(self, args) -> None:
        """Initialize overlap-summary paths and analysis settings."""
        self.input_prefix = str(args.input)
        self.output_prefix = str(
            args.output if args.output else self.input_prefix + "_summary"
        )
        self.significance_metric = str(args.significance_metric).lower()
        self.significance_cutoff = float(args.significance_cutoff)
        self.draw_plot = bool(args.plot)
        self.output_format = str(args.output_format)
        self.dpi = int(args.dpi)
        self.font_size = float(args.font_size)
        self.top_specific_genes = int(args.top_specific_genes)

        self.overlap_summary_file = Path(self.input_prefix + ".summary.txt")
        self.shared_peak_file = Path(self.input_prefix + ".shared.peaks.txt")
        self.shared_cluster_file = Path(self.input_prefix + ".shared.clusters.txt")
        self.relationship_file = Path(self.input_prefix + ".relationships.txt")

        self.sample_a = ""
        self.sample_b = ""
        self.sample_key_a = ""
        self.sample_key_b = ""
        self.sample_order: list[str] = []
        self.specific_file_a = Path()
        self.specific_file_b = Path()

        self.overlap_summary = pd.DataFrame()
        self.shared_peaks = pd.DataFrame()
        self.specific_a = pd.DataFrame()
        self.specific_b = pd.DataFrame()
        self.peak_table = pd.DataFrame()
        self.shared_clusters = pd.DataFrame()
        self.relationships = pd.DataFrame()

        self.category_summary = pd.DataFrame()
        self.transcript_summary = pd.DataFrame()
        self.gene_summary = pd.DataFrame()
        self.cluster_summary = pd.DataFrame()
        self.region_summary = pd.DataFrame()
        self.overlap_quality_summary = pd.DataFrame()
        self.significant_specific = pd.DataFrame()
        self.summary_table = pd.DataFrame()

    @staticmethod
    def _sanitize_label(label: str) -> str:
        """Convert a condition label to the filename convention used by serp_overlap."""
        cleaned = re.sub(r"[^A-Za-z0-9._-]+", "_", str(label).strip())
        cleaned = cleaned.strip("._-")
        return cleaned if cleaned else "sample"

    @staticmethod
    def _safe_numeric(series: pd.Series) -> pd.Series:
        """Convert one Series to numeric values while preserving missing values."""
        return pd.to_numeric(series.replace("-", pd.NA), errors="coerce")

    @staticmethod
    def _valid_gene_count(table: pd.DataFrame) -> int:
        """Count non-placeholder gene names in one table."""
        if "gene_name" not in table.columns or table.empty:
            return 0
        values = table["gene_name"].fillna("-").astype(str).str.strip()
        values = values.loc[~values.isin(["", "-", "nan", "None"])]
        return int(values.nunique())

    @staticmethod
    def _read_table(path: Path) -> pd.DataFrame:
        """Read one tab-separated table while retaining empty tables with headers."""
        if not path.exists():
            raise FileNotFoundError("Required overlap result does not exist: {0}".format(path))
        return pd.read_csv(path, sep="\t", low_memory=False)

    @staticmethod
    def _require_columns(
        table: pd.DataFrame,
        required: set[str],
        label: str,
    ) -> None:
        """Validate required columns in one input table."""
        missing = sorted(required.difference(table.columns))
        if missing:
            raise ValueError(
                "{0} is missing required column(s): {1}".format(
                    label,
                    ", ".join(missing),
                )
            )

    def _resolve_samples(self) -> None:
        """Resolve the two biological-condition labels from overlap summary columns."""
        columns = [
            str(column)
            for column in self.overlap_summary.columns
            if str(column) not in {"metric", "comparison"}
        ]
        if len(columns) != 2:
            raise ValueError(
                "Expected exactly two condition columns in {0}; found: {1}".format(
                    self.overlap_summary_file,
                    ", ".join(columns),
                )
            )
        self.sample_a, self.sample_b = columns
        if self.sample_a == self.sample_b:
            raise ValueError("Overlap summary contains duplicate condition labels.")
        self.sample_order = [self.sample_a, self.sample_b]
        self.sample_key_a = self._sanitize_label(self.sample_a)
        self.sample_key_b = self._sanitize_label(self.sample_b)
        if self.sample_key_a == self.sample_key_b:
            raise ValueError(
                "Condition labels produce identical filename-safe identifiers: {0}.".format(
                    self.sample_key_a
                )
            )

        label_a = self.sample_key_a
        label_b = self.sample_key_b
        self.specific_file_a = Path(
            self.input_prefix + "." + label_a + ".specific.peaks.txt"
        )
        self.specific_file_b = Path(
            self.input_prefix + "." + label_b + ".specific.peaks.txt"
        )

    def _standardize_peak_table(
        self,
        table: pd.DataFrame,
        expected_category: str,
        source_label: str,
    ) -> pd.DataFrame:
        """Standardize one shared or specific peak table."""
        self._require_columns(table, self.REQUIRED_SHARED_COLUMNS, source_label)
        table = table.copy()

        table["comparison_sample"] = (
            table["comparison_sample"].fillna("").astype(str)
        )
        unexpected_samples = sorted(
            set(table["comparison_sample"].dropna().astype(str))
            .difference(self.sample_order)
            .difference({""})
        )
        if unexpected_samples:
            raise ValueError(
                "{0} contains condition label(s) absent from overlap summary: {1}".format(
                    source_label,
                    ", ".join(unexpected_samples),
                )
            )

        for column in [
            "peak_num",
            "peak_length",
            "peak_start",
            "peak_end",
            "core_span_length",
            "core_length_used",
            "match_start",
            "match_end",
            "match_span_length",
            "max_fold",
            "mean_fold",
            "ck_peak_rpm",
            "ip_peak_rpm",
            "P_Value",
            "BHFDR",
        ]:
            if column in table.columns:
                table[column] = self._safe_numeric(table[column])

        if "core_length_used" in table.columns:
            table["summary_peak_length"] = table["core_length_used"]
        elif "peak_length" in table.columns:
            table["summary_peak_length"] = table["peak_length"]
        else:
            table["summary_peak_length"] = (
                self._safe_numeric(table["peak_end"])
                - self._safe_numeric(table["peak_start"])
                + 1
            )

        span_fallback = (
            self._safe_numeric(table["peak_end"])
            - self._safe_numeric(table["peak_start"])
            + 1
        )
        table["summary_peak_length"] = self._safe_numeric(
            table["summary_peak_length"]
        ).fillna(span_fallback)

        table["peak_category"] = expected_category
        table["peak_group"] = np.where(
            expected_category == "shared",
            "shared",
            table["comparison_sample"].astype(str) + "_specific",
        )

        if "Peak_loci" in table.columns:
            region = table["Peak_loci"].fillna("unknown").astype(str).str.strip()
            region = region.replace({"": "unknown", "-": "unknown"})
            table["peak_region"] = region
        else:
            table["peak_region"] = "unknown"

        if self.significance_metric == "none":
            table["significance_value"] = np.nan
            table["significance_status"] = "untested"
        else:
            metric_column = (
                "BHFDR" if self.significance_metric == "bhfdr" else "P_Value"
            )
            if metric_column not in table.columns:
                table["significance_value"] = np.nan
                table["significance_status"] = "untested"
            else:
                values = self._safe_numeric(table[metric_column])
                table["significance_value"] = values
                table["significance_status"] = np.select(
                    [
                        values.notna() & (values <= self.significance_cutoff),
                        values.notna() & (values > self.significance_cutoff),
                    ],
                    ["significant", "not_significant"],
                    default="untested",
                )

        table["significance_metric"] = self.significance_metric
        table["significance_cutoff"] = self.significance_cutoff
        table["is_testable"] = table["significance_status"].ne("untested")
        table["is_significant"] = table["significance_status"].eq("significant")
        table["is_specific"] = table["peak_category"].eq("specific")
        table["is_significant_specific"] = (
            table["is_specific"] & table["is_significant"]
        )
        return table

    def _check_disjoint_peak_classes(self) -> None:
        """Verify that shared and specific peak sets do not contain duplicate peak IDs."""
        if "peak_uid" not in self.peak_table.columns:
            return
        ids = self.peak_table["peak_uid"].dropna().astype(str)
        duplicate = ids[ids.duplicated(keep=False)]
        if duplicate.empty:
            return

        duplicate_rows = self.peak_table.loc[
            self.peak_table["peak_uid"].astype(str).isin(set(duplicate)),
            ["comparison_sample", "peak_uid", "peak_category"],
        ].sort_values(["comparison_sample", "peak_uid"])
        raise ValueError(
            "The same peak_uid occurs in multiple summary rows. Example:\n{0}".format(
                duplicate_rows.head(10).to_string(index=False)
            )
        )

    def read_results(self) -> None:
        """Read and validate the complete output set generated by serp_overlap."""
        self.overlap_summary = self._read_table(self.overlap_summary_file)
        if "metric" not in self.overlap_summary.columns:
            raise ValueError(
                "Overlap summary is missing the metric column: {0}".format(
                    self.overlap_summary_file
                )
            )
        self._resolve_samples()

        shared = self._read_table(self.shared_peak_file)
        specific_a = self._read_table(self.specific_file_a)
        specific_b = self._read_table(self.specific_file_b)
        clusters = self._read_table(self.shared_cluster_file)
        relationships = self._read_table(self.relationship_file)

        self.shared_peaks = self._standardize_peak_table(
            shared,
            expected_category="shared",
            source_label=str(self.shared_peak_file),
        )
        self.specific_a = self._standardize_peak_table(
            specific_a,
            expected_category="specific",
            source_label=str(self.specific_file_a),
        )
        self.specific_b = self._standardize_peak_table(
            specific_b,
            expected_category="specific",
            source_label=str(self.specific_file_b),
        )

        self._require_columns(
            clusters,
            self.REQUIRED_CLUSTER_COLUMNS,
            str(self.shared_cluster_file),
        )
        self._require_columns(
            relationships,
            self.REQUIRED_RELATIONSHIP_COLUMNS,
            str(self.relationship_file),
        )
        self.shared_clusters = clusters.copy()
        self.relationships = relationships.copy()

        self.peak_table = pd.concat(
            [self.shared_peaks, self.specific_a, self.specific_b],
            ignore_index=True,
            sort=False,
        )
        self._check_disjoint_peak_classes()

        for sample in self.sample_order:
            if sample not in set(self.peak_table["comparison_sample"].astype(str)):
                print(
                    "Warning: condition {0} has no retained peaks in overlap outputs.".format(
                        sample
                    ),
                    flush=True,
                )

        print(
            "Overlap peaks: total={0:,}, shared rows={1:,}, specific rows={2:,}.".format(
                len(self.peak_table),
                len(self.shared_peaks),
                len(self.specific_a) + len(self.specific_b),
            ),
            flush=True,
        )

    def _category_row(
        self,
        sample: str,
        category: str,
        table: pd.DataFrame,
    ) -> dict[str, object]:
        """Calculate summary metrics for one sample/category subset."""
        length = self._safe_numeric(table.get("summary_peak_length", pd.Series(dtype=float)))
        max_fold = self._safe_numeric(table.get("max_fold", pd.Series(dtype=float)))
        mean_fold = self._safe_numeric(table.get("mean_fold", pd.Series(dtype=float)))
        testable = table.get("is_testable", pd.Series(False, index=table.index)).astype(bool)
        significant = table.get(
            "is_significant", pd.Series(False, index=table.index)
        ).astype(bool)
        not_significant = table.get(
            "significance_status", pd.Series("untested", index=table.index)
        ).eq("not_significant")
        untested = ~testable

        testable_count = int(testable.sum())
        significant_count = int(significant.sum())
        return {
            "sample": sample,
            "category": category,
            "peak_count": int(len(table)),
            "transcript_count": int(table["transcripts"].nunique()) if len(table) else 0,
            "gene_count": self._valid_gene_count(table),
            "testable_peak_count": testable_count,
            "significant_peak_count": significant_count,
            "not_significant_peak_count": int(not_significant.sum()),
            "untested_peak_count": int(untested.sum()),
            "significant_fraction_testable": (
                float(significant_count / testable_count)
                if testable_count > 0
                else np.nan
            ),
            "mean_peak_length": float(length.mean()) if length.notna().any() else np.nan,
            "median_peak_length": float(length.median()) if length.notna().any() else np.nan,
            "mean_max_fold": float(max_fold.mean()) if max_fold.notna().any() else np.nan,
            "median_max_fold": float(max_fold.median()) if max_fold.notna().any() else np.nan,
            "mean_mean_fold": float(mean_fold.mean()) if mean_fold.notna().any() else np.nan,
            "median_mean_fold": float(mean_fold.median()) if mean_fold.notna().any() else np.nan,
        }

    def _build_category_summary(self) -> None:
        """Build all/shared/specific summary rows for each condition."""
        rows: list[dict[str, object]] = []
        for sample in self.sample_order:
            sample_table = self.peak_table.loc[
                self.peak_table["comparison_sample"].astype(str).eq(sample)
            ]
            rows.append(self._category_row(sample, "all", sample_table))
            rows.append(
                self._category_row(
                    sample,
                    "shared",
                    sample_table.loc[sample_table["peak_category"].eq("shared")],
                )
            )
            rows.append(
                self._category_row(
                    sample,
                    "specific",
                    sample_table.loc[sample_table["peak_category"].eq("specific")],
                )
            )
        self.category_summary = pd.DataFrame(rows)

    @staticmethod
    def _classification_from_counts(
        row: pd.Series,
        sample_key_a: str,
        sample_key_b: str,
    ) -> str:
        """Classify one transcript or gene from shared and specific peak counts."""
        shared = int(row.get("shared_cluster_count", 0)) > 0
        a_specific = int(row.get(sample_key_a + "_specific_peak_count", 0)) > 0
        b_specific = int(row.get(sample_key_b + "_specific_peak_count", 0)) > 0

        if shared and a_specific and b_specific:
            return "shared_plus_both_specific"
        if shared and a_specific:
            return "shared_plus_{0}_specific".format(sample_key_a)
        if shared and b_specific:
            return "shared_plus_{0}_specific".format(sample_key_b)
        if shared:
            return "shared_only"
        if a_specific and b_specific:
            return "both_specific"
        if a_specific:
            return "{0}_specific_only".format(sample_key_a)
        if b_specific:
            return "{0}_specific_only".format(sample_key_b)
        return "unclassified"

    def _build_entity_summary(self, entity_column: str) -> pd.DataFrame:
        """Build transcript- or gene-level shared/specific peak counts."""
        base_columns = [entity_column, "shared_cluster_count"]
        for sample_key in [self.sample_key_a, self.sample_key_b]:
            base_columns.extend(
                [
                    sample_key + "_shared_peak_count",
                    sample_key + "_significant_shared_peak_count",
                    sample_key + "_specific_peak_count",
                    sample_key + "_significant_specific_peak_count",
                ]
            )
        if entity_column == "gene_name":
            base_columns.append("transcript_count")
        base_columns.append("peak_pattern")

        if entity_column not in self.peak_table.columns:
            return pd.DataFrame(columns=base_columns)

        table = self.peak_table.copy()
        table[entity_column] = table[entity_column].fillna("-").astype(str)
        if entity_column == "gene_name":
            table = table.loc[~table[entity_column].isin(["", "-", "nan", "None"])]
        if table.empty:
            return pd.DataFrame(columns=base_columns)

        shared = table.loc[table["peak_category"].eq("shared")].copy()
        if "shared_cluster_id" in shared.columns:
            shared_cluster_count = (
                shared.loc[~shared["shared_cluster_id"].astype(str).isin(["", "-", "nan"])]
                .groupby(entity_column)["shared_cluster_id"]
                .nunique()
                .rename("shared_cluster_count")
            )
        else:
            shared_cluster_count = shared.groupby(entity_column).size().rename(
                "shared_cluster_count"
            )
        pieces = [shared_cluster_count]

        sample_pairs = [
            (self.sample_a, self.sample_key_a),
            (self.sample_b, self.sample_key_b),
        ]
        for sample, sample_key in sample_pairs:
            sample_table = table.loc[
                table["comparison_sample"].astype(str).eq(sample)
            ]
            sample_shared = sample_table.loc[sample_table["peak_category"].eq("shared")]
            sample_specific = sample_table.loc[sample_table["peak_category"].eq("specific")]
            pieces.append(
                sample_shared.groupby(entity_column)
                .size()
                .rename(sample_key + "_shared_peak_count")
            )
            pieces.append(
                sample_shared.loc[sample_shared["is_significant"]]
                .groupby(entity_column)
                .size()
                .rename(sample_key + "_significant_shared_peak_count")
            )
            pieces.append(
                sample_specific.groupby(entity_column)
                .size()
                .rename(sample_key + "_specific_peak_count")
            )
            pieces.append(
                sample_specific.loc[sample_specific["is_significant"]]
                .groupby(entity_column)
                .size()
                .rename(sample_key + "_significant_specific_peak_count")
            )

        result = pd.concat(pieces, axis=1).fillna(0).reset_index()
        count_columns = [column for column in result.columns if column.endswith("_count")]
        result[count_columns] = result[count_columns].astype(int)

        if entity_column == "gene_name":
            transcript_counts = (
                table.groupby("gene_name")["transcripts"]
                .nunique()
                .rename("transcript_count")
                .reset_index()
            )
            result = result.merge(
                transcript_counts,
                on="gene_name",
                how="left",
                validate="one_to_one",
            )

        result["peak_pattern"] = result.apply(
            self._classification_from_counts,
            axis=1,
            sample_key_a=self.sample_key_a,
            sample_key_b=self.sample_key_b,
        )
        sort_columns = [
            self.sample_key_a + "_significant_specific_peak_count",
            self.sample_key_b + "_significant_specific_peak_count",
            self.sample_key_a + "_specific_peak_count",
            self.sample_key_b + "_specific_peak_count",
            "shared_cluster_count",
        ]
        result = result.sort_values(
            sort_columns,
            ascending=[False] * len(sort_columns),
            kind="stable",
        ).reset_index(drop=True)
        return result

    def _build_cluster_summary(self) -> None:
        """Annotate shared clusters with relationship class and significance counts."""
        clusters = self.shared_clusters.copy()
        if clusters.empty:
            self.cluster_summary = clusters
            return

        for column in ["peak_count_a", "peak_count_b"]:
            clusters[column] = self._safe_numeric(clusters[column]).fillna(0).astype(int)

        conditions = [
            (clusters["peak_count_a"].eq(1) & clusters["peak_count_b"].eq(1)),
            (clusters["peak_count_a"].eq(1) & clusters["peak_count_b"].gt(1)),
            (clusters["peak_count_a"].gt(1) & clusters["peak_count_b"].eq(1)),
            (clusters["peak_count_a"].gt(1) & clusters["peak_count_b"].gt(1)),
        ]
        clusters["relationship_class"] = np.select(
            conditions,
            ["1:1", "1:N", "N:1", "N:N"],
            default="other",
        )

        shared = self.shared_peaks.copy()
        if "shared_cluster_id" not in shared.columns:
            self.cluster_summary = clusters
            return

        stats_rows: list[dict[str, object]] = []
        for cluster_id, table in shared.groupby("shared_cluster_id", sort=False):
            row: dict[str, object] = {"cluster_id": cluster_id}
            for sample, sample_key in [
                (self.sample_a, self.sample_key_a),
                (self.sample_b, self.sample_key_b),
            ]:
                one = table.loc[table["comparison_sample"].astype(str).eq(sample)]
                row[sample_key + "_peak_count"] = int(len(one))
                row[sample_key + "_testable_peak_count"] = int(one["is_testable"].sum())
                row[sample_key + "_significant_peak_count"] = int(one["is_significant"].sum())
            a_sig = int(row.get(self.sample_key_a + "_significant_peak_count", 0)) > 0
            b_sig = int(row.get(self.sample_key_b + "_significant_peak_count", 0)) > 0
            a_test = int(row.get(self.sample_key_a + "_testable_peak_count", 0)) > 0
            b_test = int(row.get(self.sample_key_b + "_testable_peak_count", 0)) > 0
            if a_sig and b_sig:
                status = "both_significant"
            elif a_sig:
                status = self.sample_a + "_significant_only"
            elif b_sig:
                status = self.sample_b + "_significant_only"
            elif not a_test and not b_test:
                status = "untested"
            else:
                status = "no_significant_peak"
            row["cluster_significance"] = status
            stats_rows.append(row)

        cluster_stats = pd.DataFrame(stats_rows)
        self.cluster_summary = clusters.merge(
            cluster_stats,
            on="cluster_id",
            how="left",
            validate="one_to_one",
        )

    def _build_region_summary(self) -> None:
        """Summarize peak-locus annotations by condition and peak category."""
        if self.peak_table.empty:
            self.region_summary = pd.DataFrame()
            return
        region = (
            self.peak_table.groupby(
                ["comparison_sample", "peak_category", "peak_region"],
                dropna=False,
            )
            .size()
            .rename("peak_count")
            .reset_index()
        )
        totals = region.groupby(
            ["comparison_sample", "peak_category"]
        )["peak_count"].transform("sum")
        region["peak_fraction"] = np.where(totals > 0, region["peak_count"] / totals, 0.0)
        self.region_summary = region.sort_values(
            ["comparison_sample", "peak_category", "peak_count"],
            ascending=[True, True, False],
            kind="stable",
        ).reset_index(drop=True)

    def _build_overlap_quality_summary(self) -> None:
        """Summarize qualifying shared-relationship geometry."""
        rel = self.relationships.copy()
        if rel.empty:
            self.overlap_quality_summary = pd.DataFrame(
                columns=["metric", "n", "mean", "median", "std", "min", "q1", "q3", "max"]
            )
            return

        if "qualifying_overlap" in rel.columns:
            qualified = rel["qualifying_overlap"].astype(str).str.lower().isin(
                ["true", "1", "yes"]
            )
            rel = rel.loc[qualified].copy()

        metrics = [
            "overlap_length",
            "overlap_fraction_a",
            "overlap_fraction_b",
            "reciprocal_overlap",
            "jaccard",
            "center_shift_b_minus_a",
            "core_length_difference_b_minus_a",
            "span_length_difference_b_minus_a",
        ]
        rows: list[dict[str, object]] = []
        for metric in metrics:
            if metric not in rel.columns:
                continue
            values = self._safe_numeric(rel[metric]).dropna().astype(float)
            if values.empty:
                continue
            rows.append(
                {
                    "metric": metric,
                    "n": int(len(values)),
                    "mean": float(values.mean()),
                    "median": float(values.median()),
                    "std": float(values.std(ddof=1)) if len(values) > 1 else np.nan,
                    "min": float(values.min()),
                    "q1": float(values.quantile(0.25)),
                    "q3": float(values.quantile(0.75)),
                    "max": float(values.max()),
                }
            )
        self.overlap_quality_summary = pd.DataFrame(rows)

    def _build_global_summary(self) -> None:
        """Build compact top-level summary metrics for both conditions."""
        metrics: list[tuple[str, object, object, object]] = []
        category = self.category_summary.set_index(["sample", "category"])

        def value(sample: str, category_name: str, column: str) -> object:
            key = (sample, category_name)
            if key not in category.index:
                return 0
            result = category.loc[key, column]
            return result.item() if hasattr(result, "item") else result

        for metric_name, column in [
            ("total_peak_count", "peak_count"),
            ("shared_peak_count", "peak_count"),
            ("specific_peak_count", "peak_count"),
            ("testable_peak_count", "testable_peak_count"),
            ("significant_peak_count", "significant_peak_count"),
            ("significant_specific_peak_count", "significant_peak_count"),
            ("untested_peak_count", "untested_peak_count"),
        ]:
            if metric_name in {"total_peak_count", "testable_peak_count", "significant_peak_count", "untested_peak_count"}:
                category_name = "all"
            elif metric_name == "shared_peak_count":
                category_name = "shared"
            else:
                category_name = "specific"
            metrics.append(
                (
                    metric_name,
                    value(self.sample_a, category_name, column),
                    value(self.sample_b, category_name, column),
                    "-",
                )
            )

        metrics.extend(
            [
                (
                    "transcripts_with_specific_peaks",
                    int(self.specific_a["transcripts"].nunique()) if len(self.specific_a) else 0,
                    int(self.specific_b["transcripts"].nunique()) if len(self.specific_b) else 0,
                    "-",
                ),
                (
                    "genes_with_specific_peaks",
                    self._valid_gene_count(self.specific_a),
                    self._valid_gene_count(self.specific_b),
                    "-",
                ),
                (
                    "shared_cluster_count",
                    "-",
                    "-",
                    int(len(self.cluster_summary)),
                ),
                (
                    "qualifying_relationship_count",
                    "-",
                    "-",
                    int(
                        self.relationships["qualifying_overlap"]
                        .astype(str)
                        .str.lower()
                        .isin(["true", "1", "yes"])
                        .sum()
                    )
                    if len(self.relationships)
                    else 0,
                ),
                (
                    "significance_metric",
                    "-",
                    "-",
                    self.significance_metric,
                ),
                (
                    "significance_cutoff",
                    "-",
                    "-",
                    self.significance_cutoff,
                ),
            ]
        )
        self.summary_table = pd.DataFrame(
            metrics,
            columns=["metric", self.sample_a, self.sample_b, "comparison"],
        )

    def calculate_summary(self) -> None:
        """Calculate peak-category, entity, cluster, and overlap-quality summaries."""
        self._build_category_summary()
        self.transcript_summary = self._build_entity_summary("transcripts")
        self.gene_summary = self._build_entity_summary("gene_name")
        self._build_cluster_summary()
        self._build_region_summary()
        self._build_overlap_quality_summary()
        self.significant_specific = self.peak_table.loc[
            self.peak_table["is_significant_specific"]
        ].copy()
        self._build_global_summary()

    def _sample_significant_specific(self, sample: str) -> pd.DataFrame:
        """Return statistically significant specific peaks for one condition."""
        return self.significant_specific.loc[
            self.significant_specific["comparison_sample"].astype(str).eq(sample)
        ].copy()

    def write_tables(self) -> dict[str, str]:
        """Write all overlap-summary tables and significant-specific peak lists."""
        prefix = self.output_prefix
        Path(prefix).expanduser().resolve().parent.mkdir(parents=True, exist_ok=True)

        files = {
            "summary": prefix + ".summary.txt",
            "peak_classification": prefix + ".peak_classification.txt",
            "category_summary": prefix + ".category_summary.txt",
            "transcripts": prefix + ".transcripts.txt",
            "genes": prefix + ".genes.txt",
            "shared_clusters": prefix + ".shared.clusters.txt",
            "region_summary": prefix + ".region_summary.txt",
            "overlap_quality_summary": prefix + ".overlap_quality_summary.txt",
            "significant_specific": prefix + ".significant_specific.peaks.txt",
        }

        self.summary_table.to_csv(files["summary"], sep="\t", index=False)
        self.peak_table.to_csv(files["peak_classification"], sep="\t", index=False)
        self.category_summary.to_csv(files["category_summary"], sep="\t", index=False)
        self.transcript_summary.to_csv(files["transcripts"], sep="\t", index=False)
        self.gene_summary.to_csv(files["genes"], sep="\t", index=False)
        self.cluster_summary.to_csv(files["shared_clusters"], sep="\t", index=False)
        self.region_summary.to_csv(files["region_summary"], sep="\t", index=False)
        self.overlap_quality_summary.to_csv(
            files["overlap_quality_summary"], sep="\t", index=False
        )
        self.significant_specific.to_csv(
            files["significant_specific"], sep="\t", index=False
        )

        for sample in self.sample_order:
            safe_label = self._sanitize_label(sample)
            sample_file = prefix + "." + safe_label + ".significant_specific.peaks.txt"
            self._sample_significant_specific(sample).to_csv(
                sample_file,
                sep="\t",
                index=False,
            )
            files["significant_specific_" + safe_label] = sample_file
        return files

    def result_counts(self) -> dict[str, object]:
        """Return concise counts for command-line reporting."""
        return {
            "sample_a": self.sample_a,
            "sample_b": self.sample_b,
            "sample_a_peaks": int(
                self.peak_table["comparison_sample"].astype(str).eq(self.sample_a).sum()
            ),
            "sample_b_peaks": int(
                self.peak_table["comparison_sample"].astype(str).eq(self.sample_b).sum()
            ),
            "shared_clusters": int(len(self.cluster_summary)),
            self._sanitize_label(self.sample_a) + "_specific": int(len(self.specific_a)),
            self._sanitize_label(self.sample_b) + "_specific": int(len(self.specific_b)),
            self._sanitize_label(self.sample_a) + "_significant_specific": int(
                len(self._sample_significant_specific(self.sample_a))
            ),
            self._sanitize_label(self.sample_b) + "_significant_specific": int(
                len(self._sample_significant_specific(self.sample_b))
            ),
        }

    def draw_figures(self) -> None:
        """Draw overlap-summary figures through the dedicated plotting layer."""
        if not self.draw_plot:
            return
        from utils.serp.OverlapSummaryPlot import SeRPOverlapSummaryPlot

        plotter = SeRPOverlapSummaryPlot(
            peak_table=self.peak_table,
            category_summary=self.category_summary,
            gene_summary=self.gene_summary,
            cluster_summary=self.cluster_summary,
            relationships=self.relationships,
            sample_order=self.sample_order,
            output_prefix=self.output_prefix,
            top_specific_genes=self.top_specific_genes,
            output_format=self.output_format,
            dpi=self.dpi,
            font_size=self.font_size,
        )
        plotter.draw_all()